import videoHomePage from "../../assets/vdhome.m3u8"
const HomePage = (props) => {
    return (<div className="homepage-container">
        <video width={"100%"} height="100%" autoPlay muted loop>
            <source src={videoHomePage} 
            type="video/m3u8"/>
        </video>
    </div>)
}
export default HomePage;
